import React, { useState, useEffect, useContext } from 'react';
import { useParams, Link } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';
import { API_URL } from '../config';

const CoursePlayer = () => {
  const { id } = useParams();
  const { token } = useContext(AuthContext);

  const [course, setCourse] = useState(null);
  const [loadingCourse, setLoadingCourse] = useState(true);
  const [currentLessonId, setCurrentLessonId] = useState(null);
  const [completedLessons, setCompletedLessons] = useState([]);
  const [videoUrl, setVideoUrl] = useState('');
  const [isLoadingVideo, setIsLoadingVideo] = useState(false);
  const [accessDenied, setAccessDenied] = useState(false);

  // Charge les infos du cours (titre, liste des leçons)
  useEffect(() => {
    fetch(`${API_URL}/courses/${id}`)
      .then(res => {
        if (!res.ok) throw new Error();
        return res.json();
      })
      .then(data => {
        setCourse(data);
        if (data.lessons.length > 0) setCurrentLessonId(data.lessons[0].id);
      })
      .catch(() => setCourse(null))
      .finally(() => setLoadingCourse(false));
  }, [id]);

  const currentLesson = course?.lessons.find(l => l.id === currentLessonId);

  // À chaque changement de leçon, demande la vraie URL vidéo au serveur (vérification 403 réelle)
  useEffect(() => {
    if (!currentLessonId || !token) return;

    const fetchSecureVideo = async () => {
      setIsLoadingVideo(true);
      setAccessDenied(false);
      try {
        const res = await fetch(`${API_URL}/courses/${id}/lessons/${currentLessonId}/video`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (res.status === 403) {
          setAccessDenied(true);
          return;
        }
        if (!res.ok) throw new Error();
        const data = await res.json();
        setVideoUrl(data.video_url);
      } catch {
        setAccessDenied(true);
      } finally {
        setIsLoadingVideo(false);
      }
    };

    fetchSecureVideo();
  }, [currentLessonId, id, token]);

  const handleSecureDownload = async (type) => {
    try {
      const res = await fetch(`${API_URL}/courses/${id}/${type === 'resume' ? 'resume-pdf' : 'tp-pdf'}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.status === 403) {
        alert('Accès refusé — ce cours n\'est pas encore payé sur ce compte.');
        return;
      }
      if (!res.ok) throw new Error();
      const data = await res.json();
      window.open(data.pdf_url, '_blank');
    } catch {
      alert('Impossible de récupérer le document pour le moment.');
    }
  };

  const handleNextLesson = async () => {
    if (!completedLessons.includes(currentLessonId)) {
      setCompletedLessons([...completedLessons, currentLessonId]);
      fetch(`${API_URL}/courses/${id}/progress/${currentLessonId}`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
      }).catch(() => {});
    }

    const currentIndex = course.lessons.findIndex(l => l.id === currentLessonId);
    if (currentIndex < course.lessons.length - 1) {
      setCurrentLessonId(course.lessons[currentIndex + 1].id);
    }
  };

  if (loadingCourse) {
    return <div className="min-h-screen bg-[#0A0E1A] flex items-center justify-center text-slate-500 text-sm">Chargement...</div>;
  }

  if (!course) {
    return (
      <div className="min-h-screen bg-[#0A0E1A] flex flex-col items-center justify-center gap-4">
        <p className="text-slate-500 text-sm">Cours introuvable.</p>
        <Link to="/catalog" className="text-blue-400 hover:text-blue-300 font-semibold text-sm">← Retour au catalogue</Link>
      </div>
    );
  }

  const progressPercentage = Math.round((completedLessons.length / course.lessons.length) * 100);

  return (
    <div className="min-h-screen bg-[#0A0E1A] text-slate-200 font-sans flex flex-col md:flex-row antialiased">

      <aside className="w-full md:w-80 border-r border-slate-900 bg-[#0A0E1A] flex flex-col shrink-0">
        <div className="p-6 border-b border-slate-900">
          <Link to="/" className="text-[10px] font-mono text-blue-500 hover:underline tracking-wider uppercase mb-2 block">
            ← Retour à l'infrastructure
          </Link>
          <h2 className="text-sm font-bold text-white uppercase tracking-wide leading-tight">{course.title}</h2>
        </div>

        <div className="p-6 border-b border-slate-900 bg-slate-950/40 space-y-2">
          <div className="flex justify-between items-center text-xs font-mono">
            <span className="text-slate-400 uppercase tracking-wider">Progression</span>
            <span className="text-blue-400 font-bold">{completedLessons.length} / {course.lessons.length} Modules</span>
          </div>
          <div className="w-full bg-slate-900 h-1.5 rounded-full overflow-hidden border border-slate-800">
            <div className="bg-gradient-to-r from-blue-600 to-cyan-500 h-full rounded-full transition-all duration-500" style={{ width: `${progressPercentage}%` }}></div>
          </div>
          <div className="text-[10px] text-slate-500 font-mono text-right">{progressPercentage}% complété</div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-2">
          {course.lessons.map((lesson) => {
            const isCurrent = lesson.id === currentLessonId;
            const isCompleted = completedLessons.includes(lesson.id);
            return (
              <button
                key={lesson.id}
                onClick={() => setCurrentLessonId(lesson.id)}
                className={`w-full text-left p-3.5 rounded-lg border text-xs font-medium transition-all duration-200 flex justify-between items-center group
                  ${isCurrent ? 'bg-blue-500/5 border-blue-500 text-blue-400' : 'bg-transparent border-slate-950 text-slate-400 hover:border-slate-800 hover:text-white'}`}
              >
                <div className="flex items-center gap-3 max-w-[80%]">
                  {isCompleted ? <span className="text-emerald-400 font-bold">✓</span> : <span className="text-slate-600">•</span>}
                  <span className="truncate">{lesson.title}</span>
                </div>
                <span className="text-[10px] font-mono text-slate-600">{lesson.duration}</span>
              </button>
            );
          })}
        </div>
      </aside>

      <main className="flex-1 bg-[#0A0E1A] p-8 flex flex-col justify-between overflow-y-auto">
        <div className="mb-6 flex justify-between items-start border-b border-slate-900/60 pb-6">
          <h1 className="text-xl font-bold text-white tracking-tight">{currentLesson?.title}</h1>
        </div>

        <div className="relative aspect-video w-full bg-slate-950 rounded-xl border border-slate-900 flex items-center justify-center overflow-hidden max-w-5xl mx-auto">
          {accessDenied ? (
            <div className="text-center space-y-3 p-6">
              <div className="w-12 h-12 rounded-full bg-red-500/10 border border-red-500/30 flex items-center justify-center text-red-400 text-lg mx-auto">✕</div>
              <h3 className="text-sm font-bold text-red-400 uppercase tracking-wider">403 Forbidden</h3>
              <p className="text-xs text-slate-500 max-w-sm">Ce cours n'est pas encore payé sur ce compte.</p>
              <Link to={`/course/${id}`} className="text-blue-400 hover:text-blue-300 text-xs font-semibold inline-block mt-2">
                Débloquer ce cours →
              </Link>
            </div>
          ) : isLoadingVideo ? (
            <div className="text-center text-xs text-slate-500 uppercase tracking-widest animate-pulse">
              Vérification des droits...
            </div>
          ) : (
            <video key={videoUrl} src={videoUrl} controls controlsList="nodownload" className="w-full h-full object-cover" />
          )}
        </div>

        <div className="mt-8 max-w-5xl w-full mx-auto space-y-8">
          <div className="flex justify-end border-b border-slate-900 pb-8">
            <button
              onClick={handleNextLesson}
              disabled={course.lessons.findIndex(l => l.id === currentLessonId) === course.lessons.length - 1}
              className="bg-white hover:bg-blue-600 text-slate-950 hover:text-white px-8 py-3.5 rounded-lg text-xs font-bold uppercase tracking-widest transition-all disabled:bg-slate-900 disabled:text-slate-600"
            >
              Leçon Suivante ➔
            </button>
          </div>

          <div className="grid sm:grid-cols-2 gap-4">
            <div className="bg-slate-950/40 border border-slate-900 rounded-xl p-5 flex justify-between items-center">
              <p className="text-xs font-bold text-white">Fiche Synthèse</p>
              <button onClick={() => handleSecureDownload('resume')} className="bg-slate-900 border border-slate-800 hover:border-blue-500 text-slate-300 hover:text-blue-400 px-4 py-2 rounded text-[10px] font-bold uppercase transition-all">
                Télécharger
              </button>
            </div>
            <div className="bg-slate-950/40 border border-slate-900 rounded-xl p-5 flex justify-between items-center">
              <p className="text-xs font-bold text-white">Travaux Pratiques</p>
              <button onClick={() => handleSecureDownload('tp')} className="bg-slate-900 border border-slate-800 hover:border-blue-500 text-slate-300 hover:text-blue-400 px-4 py-2 rounded text-[10px] font-bold uppercase transition-all">
                Télécharger
              </button>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
};
export default CoursePlayer;
